module parallel2serial(
    input clk, 
    input rst_n, 
    input [3:0] d, 
    output reg valid_out, 
    output reg dout
);
// Sequential logic for the counter
reg [1:0] cnt;
reg [3:0] data;
reg valid;
// Combinational logic for dout and valid_out
assign dout = data[3];
assign valid_out = valid;
// Always block triggered on the rising edge of the clock or the negative edge of the reset signal
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        // Asynchronous reset
        cnt <= 2'b00;
        data <= 4'b0000;
        valid <= 1'b0;
    end else begin
        if (cnt == 2'b11) begin
            // Update data register with the new parallel input
            data <= d;
            // Reset the counter to 0
            cnt <= 2'b00;
            // Set the valid signal to 1
            valid <= 1'b1;
        end else begin
            // Rotate the data register left by 1 bit
            data <= {data[2:0], data[3]};
            // Increment the counter by 1
            cnt <= cnt + 1;
            // Set the valid signal to 0
            valid <= 1'b0;
        end
    end
end
endmodule
